from typing import List
class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        for l in range(n):
            for r in range(l, n):
                a = nums[:l] + nums[r + 1:]
                if all(a[i] < a[i + 1] for i in range(len(a) - 1)):
                    ans += 1
        return ans

