class Solution {
public:
    int incremovableSubarrayCount(vector<int>& nums) {
        int n = nums.size(), ans = 0;
        for (int l = 0; l < n; l++)
            for (int r = l; r < n; r++) {
                bool ok = true;
                int prev = 0;
                for (int i = 0; i < n && ok; i++) {
                    if (i >= l && i <= r) continue;
                    if (prev && nums[i] <= prev) ok = false;
                    prev = nums[i];
                }
                ans += ok;
            }
        return ans;
    }
};

