    int incremovableSubarrayCount(vector<int>& nums) {
        int n = nums.size();
        vector<bool> incTo(n, true);
        for (int i = 1; i < n; i++) incTo[i] = incTo[i - 1] && nums[i] > nums[i - 1];
        int s = n - 1;
        while (s > 0 && nums[s - 1] < nums[s]) s--;
        long long ans = 0;
        for (int l = 0; l < n; l++) {
            if (l > 0 && !incTo[l - 1]) break;
            int prev = l > 0 ? nums[l - 1] : 0;
            int lo = max(l, s - 1);
            if (lo > n - 1) continue;
            ans += 1;
            int tLo = max(lo + 1, s);
            int pos = upper_bound(nums.begin() + tLo, nums.end(), prev) - nums.begin();
            ans += (n - 1) - tLo + 1 - (pos - tLo);
        }
        return (int)ans;
    }
};

